function show(title,html){if(dialog)dialog.close();const d=document.createElement('dialog');dialog=d;d.className='ec-dialog hi-dialog';d.innerHTML='<header><h2>'+e(title)+'</h2><button type="button" aria-label="关闭">×</button></header><div class="ec-dialog-body">'+html+'</div>';document.body.append(d);d.querySelector('header button').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(dialog===d)dialog=null;},{once:true});d.showModal();return d;}
