function ring(id,entries,title,sub=''){const instance=echarts.init($(id));chartList.push(instance);const total=entries.reduce((s,r)=>s+r[1],0);instance.setOption({color:colors,title:{text:title,subtext:sub,left:'center',top:'35%',textStyle:{fontSize:24,color:'#23456c'},subtextStyle:{fontSize:10}},tooltip:{trigger:'item'},series:[{type:'pie',radius:['64%','82%'],label:{show:false},data:total?entries.map(x=>({name:x[0],value:x[1]})):[{value:1,itemStyle:{color:'#e4edf8'},tooltip:{show:false}}]}]});}
