 for(let i=0;i<24;i++){const p=sample[i%12],pid='sample-plan-'+i;state.schedules.push({...p,id:'sample-schedule-'+i,recordId:null,planId:pid,title:p.problem+'随访计划',type:['常规随访','方案跟进','职业健康随访','复查提醒'][i%4],content:'核对近期实际反馈，记录执行情况与下次安排。',due:day(i%9-3),channel:i%2?'电话':'微信',owner:['王医生','刘护士','陈医生'][i%3],status:['active','pending','completed','active'][i%4],createdAt:day(-20-i)});state.tasks.push({...p,id:'sample-task-'+i,recordId:null,planId:pid,scheduleId:'sample-schedule-'+i,title:p.problem+'随访跟进',type:['电话随访','健康方案跟进','心理关怀','复查提醒'][i%4],due:day(i%7-2),time:'09:00',channel:i%2?'电话':'微信',owner:['王医生','刘护士','陈医生'][i%3],status:['pending','active','manual','overdue','unanswered','completed'][i%6],reply:i%4?'未回复':'已回复',content:'核对近期反馈、资料和下次随访安排。',logs:[]});}
 for(let i=0;i<16;i++){const p=sample[i%12];state.revisits.push({...p,id:'sample-revisit-'+i,recordId:null,title:['血压复查','血糖复查','血脂复查','体重记录'][i%4],metric:['收缩压','空腹血糖','总胆固醇','体重'][i%4],before:[160,7.6,5.92,81][i%4],after:[148,6.8,5.2,78.5][i%4],unit:['mmHg','mmol/L','mmol/L','kg'][i%4],due:day(i%7-2),status:i%4?'completed':'pending',outcome:['improved','improved','partial','unknown'][i%4],note:'复查资料已记录，管理方案由医生结合完整资料复核。',createdAt:day(-25+i)});state.care.push({...p,id:'sample-care-'+i,recordId:null,title:['压力管理关怀计划','睡眠改善关怀计划','心理支持与随访计划'][i%3],concern:['工作压力与睡眠困扰','情绪变化与支持需求','近期疲劳及生活安排'][i%3],status:['active','observation','referred','completed'][i%4],lastDue:day(-i%6-1),due:day(i%9+1),owner:['王医生','李医生'][i%2],logs:[]});}
 for(let i=0;i<18;i++){const p=sample[i%12];state.alerts.push({...p,id:'sample-alert-'+i,recordId:null,title:['血压异常','复查逾期','多项指标需复核','随访未回复','心理关怀需跟进'][i%5],content:['原始报告标记需核对，请复核指标及近期反馈。','约定复查尚未收到结果，需要联系核实。','体检结果有多项原始异常标记，待医生核对。','尚未记录本人反馈，请核实联系情况。','需由负责人员核对关怀需求及后续安排。'][i%5],owner:i%3?'王医生':'',due:day(i%4-1),createdAt:day(-i%6),status:['pending','processing','resolved','closed'][i%4],logs:[]});}
