function employeeFields(row={}){const options={'':'选择职工',...Object.fromEntries(people.map(p=>[p.id,p.name+' · '+p.code]))};return select('recordId','关联职工',options,row.recordId||'')+field('name','职工姓名 *',row.name,'text',true)+field('code','职工工号 *',row.code,'text',true)+field('org','所属单位',row.org||'')+select('risk','已确认风险等级',risks,row.risk||'unknown')+select('problem','健康问题 / 关注点',Object.fromEntries(categories.map(c=>[c,c])),row.problem||categories[0]);}
