function filterSelect(key,label,options){return select(key,label,{'':'全部',...options},filters[key]||'');}
function filterForm(extra=''){return '<form class="filters ec-filters hi-filters" id="hi-filters"><label><input type="search" name="search" maxlength="100" placeholder="职工姓名、工号或标题…" aria-label="搜索" value="'+e(filters.search||'')+'"></label>'+extra+'<button class="wb-button primary" type="submit">⌕ 查询</button>'+button('↻ 重置','reset')+'</form>';}
function filtered(){if(view==='followups')return fuFiltered();if(view==='tasks')return tsFiltered();if(ixViews.includes(view))return ixFilter();return rows().filter(r=>(!filters.search||(String(r.title)+String(r.name)+String(r.code)+String(r.content)).includes(filters.search))&&['risk','status','problem','org','owner','type'].every(key=>!filters[key]||(key==='problem'&&Array.isArray(r.problems)?r.problems.includes(filters[key]):r[key]===filters[key]))&&(!filters.from||(r.due||r.createdAt||r.start||'').slice(0,10)>=filters.from)&&(!filters.to||(r.due||r.createdAt||r.start||'').slice(0,10)<=filters.to)&&(!tab||(['pending','active','completed','overdue','unanswered','manual','pending_review','awaiting_confirmation'].includes(tab)?r.status===tab:tab==='today'?r.due===day():tab==='soon'?r.due>=day()&&r.due<=day(7):true)));}
function pagination(items){const max=Math.max(1,Math.ceil(items.length/limit));page=Math.min(page,max);visible=items.slice((page-1)*limit,page*limit);return '<div class="pagination"><span>共 '+num(items.length)+' 条</span><select id="hi-limit" aria-label="每页条数">'+[10,15,20,50].map(n=>'<option '+(n===limit?'selected':'')+'>'+n+'</option>').join('')+'</select><nav>'+button('‹','prev')+[...new Set([1,page-1,page,page+1,max])].filter(x=>x>0&&x<=max).sort((a,b)=>a-b).map(n=>'<button data-page="'+n+'" '+(n===page?'aria-current="page"':'')+'>'+n+'</button>').join('')+button('›','next')+'</nav></div>';}
function riskEntries(items){return ['critical','high','medium','low','unknown'].map(k=>[risks[k],items.filter(r=>r.risk===k).length]);}
function monthlySeries(items,statuses){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');});return {dates:months,series:statuses.map(s=>[labels[s],months.map(m=>items.filter(r=>r.status===s&&(r.createdAt||day()).slice(0,7)<=m).length)])};}
function topTools(html){return '<div class="ec-toolbar hi-toolbar"><div class="ec-actions">'+html+'</div></div>';}
function actionCell(row,extra=''){return '<td><div class="ec-row-actions">'+link(view==='plans'?'查看方案':'详情','detail',row.id)+extra+'</div></td></tr>';}
function actualPlans(){return state.plans.filter(r=>!String(r.id).startsWith('sample-')&&r.recordId&&person(r.recordId)).map(r=>({...r,name:person(r.recordId).name,code:person(r.recordId).code,org:person(r.recordId).org,risk:person(r.recordId).risk||'unknown'}));}
function planRoster(){const plans=actualPlans(),linked=new Set(plans.map(r=>r.recordId));return [...plans,...people.filter(p=>!linked.has(p.id)).map(p=>({id:'roster:'+p.id,recordId:p.id,name:p.name,code:p.code,org:p.org,risk:p.risk||'unknown',problem:'未记录',title:'尚未建立健康方案',status:'no_plan',unplanned:true,followDone:0,followTotal:0,createdAt:'',nextDue:'',content:''}))];}
