function ixAttend(id){const r=ixPick(id);if(['completed','cancelled'].includes(r.status))throw Error('已结束项目不能新增参与记录');const members=(r.memberIds||[r.recordId]).map(id=>person(id)).filter(Boolean);if(!members.length)throw Error('请先编辑项目并关联真实覆盖职工');ixForm('登记实际参与 / 完成 · '+r.title,'<div class="fu-form-grid">'+fuSelect('member','实际参与职工 *',{'':'请选择',...Object.fromEntries(members.map(p=>[p.id,p.name+' / '+p.code]))})+fuSelect('kind','实际登记事项',{attendance:'实际参加',completion:'完成本次活动',points:'积分调整（不新增参与人次）'})+fuLabel('occurredAt','实际发生时间 *',day()+'T'+new Date().toTimeString().slice(0,5),'datetime-local','required')+fuLabel('points','本次实际积分（可负值更正）',0,'number','step="1" min="-1000" max="1000" required')+fuArea('note','实际参加 / 完成依据及积分说明 *','',1500)+'<label class="fu-span fu-checks"><input type="checkbox" name="verified" required> 已核实本人实际参与情况及积分依据</label></div><p class="fu-info">完成记录同时计入一次参与；积分调整不增加人次。所有记录保留，不直接改写历史。</p>',async fd=>{const v=Object.fromEntries(fd),points=Number(v.points);if(!v.member||!v.note.trim()||!fd.has('verified'))throw Error('请补全实际参与者和依据，并勾选已核实');if(!Number.isInteger(points)||Math.abs(points)>1000||Number(r.points||0)+points<0)throw Error('积分须为-1000至1000的整数，累计积分不能小于0');if(new Date(v.occurredAt)>new Date(Date.now()+300000))throw Error('实际发生时间不能在未来');await save(()=>{const row=ixRaw(r.id);row.memberIds=row.memberIds||[row.recordId];if(row.hubVersion!==1){row.legacyParticipants=Number(row.participants||0);row.legacyDone=Number(row.done||0);row.legacyPoints=Number(row.points||0);}row.hubVersion=1;row.entries=row.entries||[];row.entries.push({id:uid(),recordId:v.member,kind:v.kind,points,occurredAt:v.occurredAt,note:v.note,actor:account.user,verified:true});row.participants=Number(row.legacyParticipants||0)+row.entries.filter(x=>['attendance','completion'].includes(x.kind)).length;row.done=Number(row.legacyDone||0)+row.entries.filter(x=>x.kind==='completion').length;row.points=Number(row.legacyPoints||0)+row.entries.reduce((n,x)=>n+Number(x.points||0),0);ixLog(row,'登记健康促进实际参与',person(v.member).name+' · '+v.note,'participation');});});}
