function ixLedger(pointsOnly=false){const items=ixRows(),d=ixModal(pointsOnly?'实际积分台账':'活动参与记录','<div class="ix-ledger-filters"><select id="ix-ledger-project">'+opt('','全部项目')+items.map(r=>opt(r.id,r.title)).join('')+'</select><input id="ix-ledger-search" placeholder="搜索真实职工姓名 / 工号"><button class="wb-button" id="ix-ledger-export">导出当前记录</button></div><div class="hp-table-scroll"><table class="hp-table"><thead><tr>'+['项目','职工 / 工号','实际时间','事项','积分','经办账号','实际依据'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody id="ix-ledger-body"></tbody></table></div><p class="fu-info">台账只列出逐项留存的实际记录。历史汇总数字没有明细时，不推造姓名与发生时间。</p><footer><button class="wb-button" id="ix-close">关闭</button></footer>');let filtered=[];function paint(){const project=d.querySelector('#ix-ledger-project').value,q=d.querySelector('#ix-ledger-search').value.trim();filtered=items.filter(r=>!project||r.id===project).flatMap(r=>(r.entries||[]).map(x=>({...x,title:r.title,person:person(x.recordId)}))).filter(x=>x.person&&(!pointsOnly||x.points!==0)&&(!q||(x.person.name+' '+x.person.code).includes(q)));d.querySelector('#ix-ledger-body').innerHTML=filtered.length?filtered.map(x=>'<tr><td>'+e(x.title)+'</td><td>'+e(x.person.name+' / '+x.person.code)+'</td><td>'+e(x.occurredAt)+'</td><td>'+e(({attendance:'实际参加',completion:'活动完成',points:'积分调整'})[x.kind])+'</td><td>'+e(x.points)+'</td><td>'+e(x.actor||'未记录')+'</td><td>'+e(x.note)+'</td></tr>').join(''):'<tr><td colspan="7" class="ec-empty">暂无匹配的逐项实际记录</td></tr>'; }d.querySelector('#ix-ledger-project').onchange=paint;d.querySelector('#ix-ledger-search').oninput=paint;d.querySelector('#ix-ledger-export').onclick=()=>{if(!filtered.length){toast('没有可导出的实际记录');return;}hpWorkbook(pointsOnly?'健康促进积分台账':'健康促进活动记录',[['项目','姓名','工号','时间','事项','积分','经办账号','依据'],...filtered.map(x=>[x.title,x.person.name,x.person.code,x.occurredAt,x.kind,x.points,x.actor,x.note])],'实际记录');};d.querySelector('#ix-close').onclick=()=>d.close();paint();}
