async function ixAction(act,id){if(act==='ix-new'||act==='ix-edit'||act==='ix-draft'){await ixEditor(act==='ix-edit'?id:'',act==='ix-draft');return;}if(act==='ix-detail'||act==='ix-records'||act==='ix-selected'){ixDetails(act==='ix-selected'?ixPick().id:id,act==='ix-records');return;}if(act==='ix-result'){ixResult(id);return;}if(act==='ix-compare'){ixCompare(id);return;}if(act==='ix-adjust'){ixAdjust(id);return;}if(act==='ix-assign'){await ixAssign();return;}if(act==='ix-handle'||act==='ix-escalate'){ixHandle(id,act==='ix-escalate');return;}if(act==='ix-contact'){ixContact(id);return;}if(act==='ix-refer'){ixRefer(id);return;}if(act==='ix-follow'){await ixFollow(id);return;}if(act==='ix-evaluate'){if(view==='promotion')ixProjectEvaluate(id);else ixCareEvaluate(id);return;}if(act==='ix-attend'){ixAttend(id);return;}if(act==='ix-ledger'||act==='ix-points'){ixLedger(act==='ix-points');return;}if(act==='ix-templates'){ixTemplates();return;}if(act==='ix-template-edit'){ixTemplateEdit(id);return;}if(act==='ix-template-use'){const r=ixPick(),t=state.settings.find(x=>x.id===id);if(r.origin==='legacy')throw Error('请到源系统使用处置流程');ixHandle(r.id);dialog.querySelector('[name=note]').value=t.content;return;}if(act==='ix-rules'){await ixRules();return;}if(act==='ix-export'||act==='ix-export-selected'){ixExport(act==='ix-export-selected');return;}if(act==='ix-legacy'){const r=ixPick(id);svc.open('dispatch',{source:'real',worker:'assess',alert:r.originalId});return;}if(act==='ix-focus'||act==='ix-clear'){filters=act==='ix-focus'?{focus:'priority'}:{};tab='';page=1;render();return;}}

