function paReport(id){const r=paReports().find(x=>x.id===id);if(!r)throw Error('报告未读取到或不可访问');const d=fuModal('体检报告 · '+(r.institution||r.id),hpSection('报告来源',hpValues([['报告编号',r.id],['版本',r.revision],['机构',r.institution],['已核验检查日期',r.examDate],['原始日期（未核验时仅供核对）',r.examDateRaw],['审核状态',paReportStatus(r)]]))+'<div class="hp-table-scroll"><table class="hp-table"><thead><tr><th>指标</th><th>原始结果</th><th>单位</th><th>原始参考范围</th><th>原始异常标记</th><th>确认状态</th></tr></thead><tbody>'+(r.items||[]).map(i=>'<tr><td>'+e(i.name)+'</td><td>'+e(i.value)+'</td><td>'+e(i.unit||'未记录')+'</td><td>'+e(i.referenceRange||'未记录')+'</td><td>'+e(i.abnormal||'未标记')+'</td><td>'+e(i.reviewStatus==='confirmed'?'已确认':'待核对')+'</td></tr>').join('')+'</tbody></table></div>'+hpSection('原件与原文建议',(r.files||[]).map(file=>'<button type="button" class="wb-button" data-pa-file="'+e(file.id)+'">'+e(file.name||'报告原件')+'</button>').join(' ')+(r.advice||[]).map(a=>'<p class="hi-pre">'+e(a.text)+'</p>').join(''))+'<footer>'+button('查看职工档案','pa-archive')+button('关闭','pa-close')+'</footer>');d.classList.add('pa-dialog');d.querySelector('[data-act=pa-close]').onclick=()=>d.close();d.querySelectorAll('[data-pa-file]').forEach(b=>b.onclick=()=>window.open(base+'ehr/api/files/'+encodeURIComponent(b.dataset.paFile),'_blank','noopener'));}
function paMaterials(kind='all'){const p=person(assistantPerson);if(!p)throw Error('请先选择真实职工');if(paEvidenceLoading)throw Error('资料正在读取中，请稍候');let html;if(kind==='reports')html=paReportsHtml();else if(kind==='assessments')html='<p class="fu-info">仅列出已确认评估，不由报告单项数值推造评分或风险等级。</p><div class="hp-table-scroll"><table class="hp-table"><thead><tr><th>评估编号</th><th>类型</th><th>风险等级</th><th>实际评分</th><th>评估时间</th><th>规则版本</th></tr></thead><tbody>'+paAssessments.map(r=>'<tr><td>'+e(r.id)+'</td><td>'+e(r.type||'未记录')+'</td><td>'+e(risks[r.level]||r.level||'未记录')+'</td><td>'+e(r.score??'未记录')+'</td><td>'+e(r.assessedAt||'未记录')+'</td><td>'+e(r.ruleVersion||'未记录')+'</td></tr>').join('')+(!paAssessments.length?'<tr><td colspan="6" class="ec-empty">暂无已确认评估</td></tr>':'')+'</tbody></table></div>';else if(kind==='followups'){const records=paFollowRecords();html=hpSection('实际随访联系记录',records.length?'<div class="hp-timeline">'+records.slice().sort((a,b)=>String(b.contactAt).localeCompare(String(a.contactAt))).map(r=>'<article><b>'+e(r.parentTitle)+'</b><p>'+e(r.contactAt)+' · '+e(({reached:'已实际联系',no_answer:'未接通',declined:'拒绝本次交流'})[r.outcome]||r.outcome)+'</p><p class="hi-pre">'+e(r.note)+'</p><small>来源：'+e(({tasks:'随访任务',schedules:'随访计划',care:'心理关怀'})[r.source])+' / '+e(r.parentId)+'</small></article>').join('')+'</div>':'<p class="ec-empty">暂无实际联系记录</p>')+hpSection('源系统随访任务（不等于实际联系）',paLegacyFollows.length?'<table class="hp-table"><thead><tr><th>任务编号</th><th>源状态</th><th>计划时间</th><th>关联报告</th></tr></thead><tbody>'+paLegacyFollows.map(r=>'<tr><td>'+e(r.id)+'</td><td>'+e(labels[r.status]||r.status||'未记录')+'</td><td>'+e(r.dueAt||'未设置')+'</td><td>'+e(r.reportId)+' / v'+e(r.revision)+'</td></tr>').join('')+'</tbody></table>':'<p class="fu-hint">暂无可读取的源系统随访任务</p>');}else if(kind==='job')html=hpSection('真实岗位与职业背景',hpValues([['职工',p.name+' / '+p.code],['所属单位',p.org],['班组',p.team],['岗位',p.job],['职业暴露',p.exposure],['当前已确认健康风险',risks[p.risk||'unknown']]]));else html=paEvidenceHtml();const d=fuModal(({reports:'关联体检报告',assessments:'已确认健康评估',followups:'实际随访记录与任务',job:'岗位信息'})[kind]||'关联资料与依据',html+'<footer>'+button('查看档案','pa-archive')+button('关闭','pa-close')+'</footer>');d.classList.add('pa-dialog');d.querySelector('[data-act=pa-close]').onclick=()=>d.close();}
function paTrends(){if(!person(assistantPerson))throw Error('请先选择真实职工');if(paEvidenceLoading)throw Error('资料正在读取中');const numeric=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/,values=paConfirmedItems().filter(i=>numeric.test(String(i.value).trim())&&i.unit).map(i=>({metric:i.name,unit:i.unit,value:Number(String(i.value).trim()),date:i.examDate||'',source:'已确认报告 '+i.reportId+' / v'+i.revision}));for(const r of state.revisits.filter(x=>x.recordId===assistantPerson&&!String(x.id).startsWith('sample-')&&x.resultDate&&x.resultSource&&ixNumber(x.after)))values.push({metric:r.metric,unit:r.unit,value:Number(r.after),date:r.resultDate,source:'实际复查 '+r.title+' · '+r.resultSource});const groups=[...new Set(values.map(v=>v.metric+'|'+v.unit))],d=fuModal('指标历史趋势','<p class="fu-info">仅展示有实际数值和来源的同指标、同单位结果；日期未核验的报告不连入时间曲线，数值变化不直接判定疗效。</p><select id="pa-trend-metric">'+(groups.length?groups.map(k=>opt(k,k.replace('|',' / '))).join(''):opt('','暂无可比较数值'))+'</select><div id="pa-trend-chart" style="height:270px"></div><div class="hp-table-scroll"><table class="hp-table"><thead><tr><th>指标</th><th>结果</th><th>单位</th><th>核验日期</th><th>来源</th></tr></thead><tbody id="pa-trend-body"></tbody></table></div><footer>'+button('关闭','pa-close')+'</footer>');let chart;function paint(){chart?.dispose();const list=values.filter(x=>x.metric+'|'+x.unit===d.querySelector('#pa-trend-metric').value).sort((a,b)=>a.date.localeCompare(b.date)),dated=list.filter(x=>x.date);d.querySelector('#pa-trend-body').innerHTML=list.length?list.map(x=>'<tr><td>'+e(x.metric)+'</td><td>'+e(x.value)+'</td><td>'+e(x.unit)+'</td><td>'+e(x.date||'日期未核验')+'</td><td>'+e(x.source)+'</td></tr>').join(''):'<tr><td colspan="5" class="ec-empty">暂无实际可比数值</td></tr>';chart=echarts.init(d.querySelector('#pa-trend-chart'));chart.setOption({color:['#1687ff'],tooltip:{trigger:'axis'},grid:{left:55,right:20,top:25,bottom:50},xAxis:{type:'category',data:dated.map(x=>x.date)},yAxis:{type:'value',name:dated[0]?.unit||'',splitLine:{lineStyle:{color:'#e8f0fa'}}},series:[{type:'line',name:'实际结果',data:dated.map(x=>x.value),symbolSize:7,connectNulls:false}]});}d.classList.add('pa-dialog');d.querySelector('#pa-trend-metric').onchange=paint;d.querySelector('[data-act=pa-close]').onclick=()=>d.close();d.addEventListener('close',()=>chart?.dispose(),{once:true});paint();}
function paPhase(phase,personOnly=false){const linked=new Set(actualPlans().map(r=>r.recordId)),items=phase==='todo'?people.filter(p=>!linked.has(p.id)):actualPlans().filter(r=>(personOnly?r.recordId===assistantPerson:phase==='review'?r.status==='pending_review':phase==='confirm'?r.status==='awaiting_confirmation':phase==='published'?['active','paused','completed'].includes(r.status):true));const d=fuModal(({todo:'未建方案的真实职工',review:'待医生审核的方案',confirm:'待职工确认的方案',published:'已发布执行的方案'})[phase]||'此职工已有方案','<input id="pa-phase-search" placeholder="搜索真实职工姓名、工号或方案名称"><div class="hp-table-scroll"><table class="hp-table"><thead><tr><th>职工</th><th>工号</th><th>'+(phase==='todo'?'所属单位':'方案名称')+'</th><th>状态</th><th>操作</th></tr></thead><tbody id="pa-phase-body"></tbody></table></div><p class="fu-hint">未建方案人数只表示当前没有关联方案的真实职工，不代表已经完成医学适用性评估。</p><footer>'+button('打开健康方案管理','pa-plan-center')+button('关闭','pa-close')+'</footer>');function paint(){const q=d.querySelector('#pa-phase-search').value.trim();const filtered=items.filter(r=>!q||[r.name,r.code,r.title].join(' ').includes(q));d.querySelector('#pa-phase-body').innerHTML=filtered.length?filtered.map(r=>'<tr><td>'+e(r.name)+'</td><td>'+e(r.code)+'</td><td>'+e(phase==='todo'?r.org:r.title)+'</td><td>'+e(phase==='todo'?'尚未建方案':labels[r.status])+'</td><td>'+button(phase==='todo'?'整理新草稿':'打开方案',phase==='todo'?'pa-open-person':'pa-open-plan','',r.id)+'</td></tr>').join(''):'<tr><td colspan="5" class="ec-empty">暂无匹配记录</td></tr>'; }d.classList.add('pa-dialog');d.querySelector('#pa-phase-search').oninput=paint;d.querySelector('[data-act=pa-close]').onclick=()=>d.close();paint();}
function paWorkflow(){const r=paPlan();if(!r)throw Error('当前草稿尚未保存');if(r.status==='pending_review'){if(!account.canReview||account.user!==r.reviewerId){fuModal('当前审核安排',hpValues([['方案',r.title],['状态',labels[r.status]],['指定审核医生',r.reviewerName||r.reviewerId],['说明','仅指定医生可记录本次审核意见']])+'<footer>'+button('关闭','pa-close')+'</footer>').querySelector('[data-act=pa-close]').onclick=()=>dialog.close();return;}const d=tsForm('医生审核健康管理方案',hpSection('完整待审核方案',paContentHtml())+'<div class="fu-form-grid">'+fuSelect('decision','实际审核结果',{approve:'审核通过，等待职工确认',reject:'退回修改'})+fuArea('note','审核意见与依据 *','',2000)+'</div>',async fd=>{const v=Object.fromEntries(fd);if(!v.note.trim())throw Error('请填写实际审核意见及依据');await save(()=>{const row=state.plans.find(x=>x.id===r.id);row.status=v.decision==='approve'?'awaiting_confirmation':'rejected';row.reviewNote=v.note;row.updatedAt=now();row.logs=row.logs||[];row.logs.push({time:now(),actor:account.user,action:v.decision==='approve'?'指定医生审核通过':'指定医生退回修改',note:v.note});});paNotice='实际审核结果已保存，尚未替职工确认或发布。';});d.classList.add('pa-dialog');return;}
 if(r.status==='awaiting_confirmation'){const d=tsForm('记录职工本人实际确认',hpSection('待确认方案',hpValues([['方案',r.title],['真实职工',r.name+' / '+r.code],['审核医生',r.reviewerName],['审核意见',r.reviewNote]]))+'<div class="fu-form-grid">'+fuLabel('confirmedAt','实际确认时间 *',day()+'T'+new Date().toTimeString().slice(0,5),'datetime-local','required')+fuSelect('method','实际确认方式',{offline:'线下实际确认',miniapp:'小程序实际确认（有回执）'})+fuArea('receipt','本人反馈、确认依据及回执说明 *','',1500)+'<label class="fu-checks fu-span"><input name="verified" type="checkbox" required> 已向职工说明方案，并取得本人实际确认</label></div>',async fd=>{const v=Object.fromEntries(fd);if(!v.receipt.trim()||!fd.has('verified'))throw Error('请填写实际确认依据并勾选已核实');if(new Date(v.confirmedAt)>new Date(Date.now()+300000))throw Error('实际确认时间不能在未来');await save(()=>{const row=state.plans.find(x=>x.id===r.id);row.status='active';row.confirmationNote=v.confirmedAt+' · '+(v.method==='miniapp'?'小程序实际回执':'线下实际确认')+' · '+v.receipt;row.assistantConfirmation={confirmedAt:v.confirmedAt,method:v.method,receipt:v.receipt,verified:true,actor:account.user};row.updatedAt=now();row.logs=row.logs||[];row.logs.push({time:now(),actor:account.user,action:'记录职工确认并发布执行',note:row.confirmationNote});});paNotice='已按实际确认记录发布执行，可在健康方案管理继续跟进。';});d.classList.add('pa-dialog');return;}
 fuModal('方案流程与记录',hpValues([['方案',r.title],['当前状态',labels[r.status]],['指定审核医生',r.reviewerName],['审核意见',r.reviewNote],['实际职工确认',r.confirmationNote]])+paChangesHtml()+'<footer>'+button('打开健康方案管理','pa-plan-center')+button('关闭','pa-close')+'</footer>').querySelector('[data-act=pa-close]').onclick=()=>dialog.close();}
async function paAction(act,id){if(act==='pa-generate'){await paGenerate();return;}if(act==='pa-edit'){paEdit();return;}if(act==='pa-save'||act==='pa-submit'){await paSave(act==='pa-submit');return;}if(act==='pa-archive'){if(!person(assistantPerson))throw Error('请先选择职工');location.href=svc.archiveLink(assistantPerson);return;}if(act==='pa-report'){paReport(id);return;}if(act==='pa-materials'){paMaterials();return;}if(act==='pa-trends'){paTrends();return;}if(act==='pa-records'){assistantTab='history';render();return;}if(act==='pa-workflow'){paWorkflow();return;}if(act==='pa-task'){if(!assistantTask)throw Error('本次尚未创建AI任务');window.DigitalWorkerDispatch.detail(assistantTask.id,()=>{});return;}if(act==='pa-stop'){++paGenerationEpoch;clearTimeout(pollTimer);aiBusy=false;paNotice='已停止本页等待；后台AI任务仍保留，可从任务详情查看实际结果。';render();return;}if(act==='pa-plan-center'){location.href=base+'manage/intervention/plans';return;}if(act==='pa-open-person'){dialog?.close();await paSelect(id);return;}if(act==='pa-open-plan'){const r=actualPlans().find(x=>x.id===id);if(!r)throw Error('方案不在当前授权范围');dialog?.close();await paSelect(r.recordId,id);return;}if(act==='pa-existing'){paPhase('all',true);return;}if(act==='pa-import'){if(!paImported?.content)throw Error('没有可导入的模板草稿');if(!person(assistantPerson))throw Error('请选择真实职工');if(paHasContent()&&!await paConfirm('应用导入的模板草稿','导入内容将覆盖当前未保存的章节，请先核对模板的适用范围。'))return;paSections=paParse(paImported.content);paSource='外部模板草稿（人工核对）';paDraftTaskId=null;paDraftSources=paSources();paDirty=true;paPlanId='';paNotice='模板草稿已应用，请逐项核对，不代表适用于此职工。';render();return;}if(act==='pa-clone'){if(!paPlan())throw Error('没有已保存方案');if(!await paConfirm('另存为新草稿','保留原方案与审核 / 确认记录，复制当前内容为新的待审核草稿。'))return;paPlanId='';paDirty=true;paSource='已有方案另存草稿';paLocalChanges=[{time:now(),actor:account.user,action:'从已有方案整理新草稿',note:'原方案状态及记录保留'}];paNotice='当前为新草稿，尚未保存或提交审核。';render();return;}}

function assistantPage(){const p=person(assistantPerson);if(!assistantDraft)assistantDraft=draftText('综合管理');const evidence=p?'<dl class="ec-description"><dt>职工姓名</dt><dd>'+e(p.name)+'</dd><dt>工号</dt><dd>'+e(p.code)+'</dd><dt>单位 / 班组</dt><dd>'+e(p.org)+' / '+e(p.team||'—')+'</dd><dt>岗位</dt><dd>'+e(p.job||'—')+'</dd><dt>职业暴露</dt><dd>'+e(p.exposure||'待核对')+'</dd><dt>风险评估</dt><dd>'+e(risks[p.risk]||'待评估')+'</dd></dl>':'<div class="ec-help">请选择职工，核对其资料后生成管理草稿。</div>';
 let body;if(assistantTab==='content')body='<div class="hi-document">'+assistantDraft.split(/\n\n/).map(part=>{const [title,...lines]=part.split('\n');return '<section><h3>'+e(title)+'</h3><p>'+e(lines.join('\n'))+'</p></section>';}).join('')+'</div>';else if(assistantTab==='evidence')body=panel('依据与职工资料',evidence+'<p class="ec-help" style="margin-top:15px">AI 任务从已关联档案中读取可访问的原件、报告和评估资料；不把空缺资料当作正常结论。</p>'+(p?button('查看关联健康档案','person-archive','primary',p.id):''));else if(assistantTab==='reports')body=panel('相关报告',p?'<p class="ec-help">在健康档案中核对报告原件、审核状态与当前版本。</p>'+button('打开职工报告与档案','person-archive','primary',p.id):'先选择职工再查看报告。');else body=panel('方案修改记录',(assistantTask?'<p class="ec-help">关联 AI 任务：'+e(assistantTask.id)+'</p>'+button('查看 AI 执行详情','ai-detail','primary'):'')+'<p class="ec-mini">方案保存后的修改可在方案管理的“记录”中查看。</p>');
 $('app').innerHTML='<div class="hi-assistant"><aside>'+panel('✧ 方案小谷','<div class="hi-bot"><span>🤖</span><div><b>为健康管理提供资料整理与草稿支持</b><p>核对职工资料，生成待审核的管理方案，保留人工审核与本人确认环节。</p></div></div><label class="ec-field">选择职工<select id="assistant-person">'+opt('','请选择职工')+people.map(x=>'<option value="'+e(x.id)+'" '+(assistantPerson===x.id?'selected':'')+'>'+e(x.name)+' · '+e(x.code)+'</option>').join('')+'</select></label><div class="hi-prompts">'+['整理最近一次体检需要核对的事项','生成个性化健康管理方案草稿','完善职业防护与随访安排'].map(text=>'<button type="button" data-prompt="'+text+'">'+text+' ›</button>').join('')+'</div>')+panel('已关联资料',evidence)+'<form id="assistant-form" class="panel ec-panel hi-composer"><label class="ec-field">本次需求<textarea id="assistant-input" maxlength="2000" rows="3" placeholder="描述希望整理的资料、关注点和管理目标…">'+e(assistantMessage)+'</textarea></label><div class="hi-ai-state" role="status">'+e(aiBusy?'任务处理中，可查看执行详情':'草稿可编辑，审核后再执行')+'</div><button type="submit" class="wb-button primary" '+(aiBusy?'disabled':'')+'>'+(aiBusy?'正在生成…':'✧ 生成方案草稿')+'</button></form></aside><div class="hi-assistant-main">'+panel('健康管理方案（待审核草稿）','<div class="ec-steps">'+['AI 生成方案','医生审核','职工确认','发布执行'].map((s,i)=>'<div class="ec-step '+(i===0?'active':'')+'"><b>'+(i+1)+'</b>'+s+'</div>').join('')+'</div>')+panel('', '<div class="ec-toolbar">'+tabs([['content','方案内容'],['evidence','依据与数据'],['reports','相关报告'],['history','修改记录']]).replaceAll('data-tab=','data-assistant-tab=').replaceAll('class="active"','class="'+(assistantTab==='content'?'active':'')+'"')+'<div class="ec-actions">'+button('编辑方案','edit-draft')+button('保存为草稿','save-draft','primary')+button('查看执行详情','ai-detail')+'</div></div>'+body)+'</div></div>';
 document.querySelectorAll('[data-assistant-tab]').forEach(b=>b.classList.toggle('active',b.dataset.assistantTab===assistantTab));$('assistant-person').onchange=event=>{if(aiBusy){toast('当前任务仍在处理，请先完成或退出任务');event.target.value=assistantPerson;return;}assistantPerson=event.target.value;requestKey=null;assistantDraft=draftText('综合管理');render();};$('assistant-form').onsubmit=event=>{event.preventDefault();const nextMessage=$('assistant-input').value;if(nextMessage!==assistantMessage)requestKey=null;assistantMessage=nextMessage;generateAI().catch(error=>{aiBusy=false;toast(error.message);render();});};}
async function generateAI(){if(aiBusy)return;const p=person(assistantPerson);if(!p)throw Error('请先选择关联职工');const prompt=assistantMessage.trim();if(!prompt)throw Error('请填写本次需要整理的资料或目标');aiBusy=true;const model=await svc.modelStatus();if(!model.configured)throw Error('AI 服务尚未配置，可先编辑并保存方案草稿');aiBusy=true;render();requestKey=requestKey||uid();const task=await svc.assign({worker:'plan',type:'plan_adjustment',title:('健康管理方案草稿 · '+p.name).slice(0,120),recordId:p.id,memberCode:p.legacyUserCode||'',priority:'normal',instructions:prompt,taskContext:{goals:prompt,currentPlan:assistantDraft.slice(0,2000)},requestKey});assistantTask=task;await svc.generate(task.id,task.version);const started=Date.now();
 const poll=async()=>{try{const result=await svc.assignment(task.id);assistantTask=result;const ai=result.ai;if(ai?.state==='succeeded'&&!ai.outdated){assistantDraft=ai.output||JSON.stringify(ai.taskResult,null,2);aiBusy=false;render();toast('方案草稿已生成，请核对后保存');return;}if(['failed','discarded'].includes(ai?.state))throw Error(ai.errorCode||'生成未完成，请查看执行详情');if(Date.now()-started>180000){aiBusy=false;render();toast('任务仍在后台排队，可在执行详情中继续查看');return;}pollTimer=setTimeout(poll,2500);}catch(error){aiBusy=false;render();toast(error.message);}};await poll();}
