function hpValues(items){return '<dl class="ec-description">'+items.map(([k,v])=>'<dt>'+e(k)+'</dt><dd class="hi-pre">'+e(v==null||v===''?'未记录':v)+'</dd>').join('')+'</dl>';}
function hpSummary(r){return '<div class="hp-summary">'+[['职工 / 工号',r.name+' / '+r.code],['所属单位',r.org],['健康问题',r.problems?.join('、')||r.problem],['方案名称',r.title],['风险等级',risks[r.risk]],['执行状态',labels[r.status]],['下次随访',r.nextDue],['创建时间',(r.createdAt||'').slice(0,10)]].map(([k,v])=>'<div><small>'+e(k)+'</small><b>'+e(v||'未记录')+'</b></div>').join('')+'</div>';}
function hpLinked(key,ids){return (state[key]||[]).filter(x=>!String(x.id).startsWith('sample-')&&person(x.recordId)&&ids.has(x.planId));}
